import{_ as e,o as a,c as n,a2 as r}from"./chunks/framework.RycU2wFZ.js";const p=JSON.parse('{"title":"Where AgentPay Fits","description":"What AgentPay does and does not do in agent infrastructure, and which components buyers, sellers, and administrators use.","frontmatter":{"title":"Where AgentPay Fits","description":"What AgentPay does and does not do in agent infrastructure, and which components buyers, sellers, and administrators use."},"headers":[],"relativePath":"learn/03-infra-map/where-agentpay-fits.md","filePath":"learn/03-infra-map/where-agentpay-fits.md","lastUpdated":1792595354000}'),o={name:"learn/03-infra-map/where-agentpay-fits.md"};function s(i,t,d,l,h,c){return a(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="where-agentpay-fits" tabindex="-1">Where AgentPay Fits <a class="header-anchor" href="#where-agentpay-fits" aria-label="Permalink to &quot;Where AgentPay Fits&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Experimental Project</p><p>AgentPay has not undergone an independent security audit. Do not use it with real production funds.</p></div><h2 id="in-a-nutshell" tabindex="-1">In a nutshell <a class="header-anchor" href="#in-a-nutshell" aria-label="Permalink to &quot;In a nutshell&quot;">​</a></h2><p>AgentPay is the <strong>financial-control layer</strong> between an agent and funds: it decides whether to allow payment before it happens and makes failures recoverable and activity traceable afterward. It is not an agent framework, a payment protocol, or a blockchain.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><p>Returning to the diagram in <a href="./agent-stack">Agent Infrastructure Layers</a>, AgentPay covers financial control and extends slightly into the adjacent layers:</p><table tabindex="0"><thead><tr><th>Capability</th><th>Description</th></tr></thead><tbody><tr><td><strong>Pre-payment policy evaluation</strong></td><td>Per-transaction caps, rolling budgets, recipient and network allowlists, rate circuit breakers, and loop detection</td></tr><tr><td><strong>Atomic budget reservation</strong></td><td>Prevents concurrent requests from exceeding the budget (see <a href="./../04-agentpay-concepts/budget-reservation">Budget Reservation</a>)</td></tr><tr><td><strong>Failure and unknown-result handling</strong></td><td>Tracks payment, settlement, and fulfillment separately; avoids blind retries when the outcome is unknown (see <a href="./../04-agentpay-concepts/timeout-is-not-failure">Timeout Is Not Failure</a>)</td></tr><tr><td><strong>Two payment rails</strong></td><td>On-chain payments (x402) and a platform virtual wallet; insufficient balance does not silently switch to the other rail</td></tr><tr><td><strong>Seller payment gateway</strong></td><td>Turns an existing API into a pay-per-request endpoint without changing its business code</td></tr><tr><td><strong>Tenant and agent management</strong></td><td>Tenant, project, and member permissions; agent and API key lifecycles; one-click disablement</td></tr><tr><td><strong>Audit and reconciliation</strong></td><td>Records requests, payments, settlement, fulfillment, and policy decisions for review by agent and session</td></tr></tbody></table><h2 id="what-it-does-not-do" tabindex="-1">What it does not do <a class="header-anchor" href="#what-it-does-not-do" aria-label="Permalink to &quot;What it does not do&quot;">​</a></h2><p>Clear boundaries are as important as clear capabilities:</p><table tabindex="0"><thead><tr><th>Not responsible for</th><th>Reason and guidance</th></tr></thead><tbody><tr><td><strong>Agent reasoning and orchestration</strong></td><td>These belong to models and frameworks such as LangChain or CrewAI. AgentPay integrates as a tool wrapper.</td></tr><tr><td><strong>Defining the payment protocol</strong></td><td>The on-chain path follows x402 V2. AgentPay uses the protocol; it does not define it (see <a href="./agentpay-vs-x402">AgentPay vs. x402</a>).</td></tr><tr><td><strong>Judging whether a service is valuable</strong></td><td>A firewall cannot tell that an allowlisted service returned a useless answer after being paid within budget.</td></tr><tr><td><strong>Custody of your private key</strong></td><td>On the on-chain path, the key stays with the buyer; the gateway and clearing service do not handle it.</td></tr><tr><td><strong>Withdrawals and transfers</strong></td><td>The current platform virtual wallet is for closed-loop spending; it does not support withdrawals or transfers between users.</td></tr><tr><td><strong>Operating a public clearing network</strong></td><td>The project provides a reference implementation, not a public clearing service.</td></tr><tr><td><strong>Surviving a compromised host</strong></td><td>If the execution environment is fully compromised, a local private key may be exposed. Stronger isolation is planned for the future.</td></tr></tbody></table><h2 id="three-roles-three-ways-to-use-it" tabindex="-1">Three roles, three ways to use it <a class="header-anchor" href="#three-roles-three-ways-to-use-it" aria-label="Permalink to &quot;Three roles, three ways to use it&quot;">​</a></h2><h3 id="buyer-safely-call-paid-services-from-an-agent" tabindex="-1">Buyer: safely call paid services from an agent <a class="header-anchor" href="#buyer-safely-call-paid-services-from-an-agent" aria-label="Permalink to &quot;Buyer: safely call paid services from an agent&quot;">​</a></h3><p>You build an agent that needs paid APIs but should not have unlimited spending authority.</p><ul><li>Use the <strong>Python SDK</strong> and configure policy on the client.</li><li>To the agent, this is an ordinary HTTP call; when a payment requirement appears, the firewall evaluates it and the signer handles authorization.</li><li>Wrap the client as a paid tool for frameworks such as LangChain.</li></ul><p>The smallest setup <strong>does not require deploying a service</strong>; the SDK and local firewall are enough.</p><h3 id="seller-turn-an-api-into-a-paid-endpoint" tabindex="-1">Seller: turn an API into a paid endpoint <a class="header-anchor" href="#seller-turn-an-api-into-a-paid-endpoint" aria-label="Permalink to &quot;Seller: turn an API into a paid endpoint&quot;">​</a></h3><p>You provide an API and want to charge per request without changing its existing code.</p><ul><li>Deploy the <strong>AgentPay Gateway</strong> as a proxy in front of the upstream service.</li><li>Configure routes, prices, payment methods, and recipient addresses in the gateway.</li><li>The gateway issues payment requirements, verifies payment, forwards requests, and avoids duplicate charges when the upstream service fails.</li></ul><p>The gateway keeps the upstream service&#39;s real credentials; they are not exposed to callers.</p><h3 id="administrator-manage-multiple-agents-and-their-funds" tabindex="-1">Administrator: manage multiple agents and their funds <a class="header-anchor" href="#administrator-manage-multiple-agents-and-their-funds" aria-label="Permalink to &quot;Administrator: manage multiple agents and their funds&quot;">​</a></h3><p>Your team or enterprise needs to manage many agents and a shared budget.</p><ul><li>Use the <strong>Web Console</strong> to configure routes and policies, edit drafts, validate and publish them, and roll back if needed.</li><li>Manage tenants, projects, members, and API keys; assign each agent its own budget and limits.</li><li>Use audit timelines to inspect what each agent did, how much it spent, and why a request was allowed or rejected.</li><li>Disable an agent with one action if its behavior becomes abnormal.</li></ul><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Purpose</th><th>Users</th></tr></thead><tbody><tr><td><strong>Python SDK</strong></td><td>Client interceptor, local policy engine, signer</td><td>Buyers</td></tr><tr><td><strong>Go Gateway</strong></td><td>Reverse proxy, payment requirements and verification, wallet debits, idempotency and recovery</td><td>Sellers and administrators</td></tr><tr><td><strong>Web Console</strong></td><td>Route and policy configuration, publish and rollback, wallets, agents, and audit</td><td>Administrators</td></tr><tr><td><strong>Clearing service (reference implementation)</strong></td><td>Validates signatures and submits on-chain settlement; includes a local simulation</td><td>Development and demos</td></tr><tr><td><strong>Specifications and test vectors</strong></td><td>Authoritative definitions for protocol, state machine, error codes, and audit events</td><td>Integrators and developers building extensions</td></tr></tbody></table><p>AgentPay can run in two forms:</p><ul><li><strong>Embedded local mode:</strong> all components run in one process without networking, suitable for development, testing, and demos (<code>make demo</code> uses this form).</li><li><strong>Distributed mode:</strong> the buyer runs in its own environment while the gateway and clearing service run in the cloud and communicate over HTTPS, matching a typical deployment.</li></ul><h2 id="current-status" tabindex="-1">Current status <a class="header-anchor" href="#current-status" aria-label="Permalink to &quot;Current status&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Status</th></tr></thead><tbody><tr><td>Python SDK and local policy engine</td><td>Complete</td></tr><tr><td>Go Gateway and wallet payment path</td><td>Complete</td></tr><tr><td>Web Console (routes, policies, publish/rollback, wallets, agents, audit)</td><td>Complete</td></tr><tr><td>TypeScript SDK</td><td>Paused; planned</td></tr><tr><td>Independent security audit</td><td>Not performed</td></tr><tr><td>Real funds in production</td><td>Not recommended</td></tr></tbody></table><p>The project is experimental. Evaluate it on testnets with test tokens first.</p><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><p><strong>Q: I only want to stop my agent from overspending. Do I need to deploy the gateway?</strong> No. The local SDK firewall can already enforce per-transaction limits, budgets, request rates, and allowlists. Use the gateway and console when you need centralized management, paid API access, or platform wallets.</p><p><strong>Q: Is AgentPay a wallet product?</strong> No. The on-chain path uses the buyer&#39;s own wallet and private key. The platform virtual wallet is an internal gateway ledger account for low-cost, low-latency small charges; it is not a public wallet application.</p><p><strong>Q: Can it work with my existing agent framework?</strong> Yes. AgentPay integrates through HTTP client interceptors and tool wrappers; you do not need to change frameworks.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>To understand how it relates to x402: <a href="./agentpay-vs-x402">AgentPay vs. x402</a></li><li>To see it in action: <a href="./../05-hands-on/ten-minute-demo">10-Minute Demo</a></li><li>To learn the design rationale: <a href="./../04-agentpay-concepts/financial-firewall">Why We Need a Financial Firewall</a></li></ul>',35)])])}const g=e(o,[["render",s]]);export{p as __pageData,g as default};
